<?php
namespace Database\Seeders;
use App\Enums\OrderStatus;use App\Models\{Customer,Order,OrderItem,Product,User};use App\Services\DeliveryService;use Illuminate\Database\Seeder;use Illuminate\Support\Facades\Hash;use Spatie\Permission\Models\Role;
class DatabaseSeeder extends Seeder {public function run():void{$roles=['Super Admin','Admin','Sales Manager','Visitor','Driver'];foreach($roles as $role)Role::firstOrCreate(['name'=>$role]);$admin=User::firstOrCreate(['mobile'=>'09120000000'],['name'=>'مدیر سامانه','username'=>'admin','email'=>'admin@example.test','password'=>Hash::make('Password123!')]);$admin->syncRoles('Super Admin');$visitors=collect(range(1,3))->map(function($i){$u=User::firstOrCreate(['mobile'=>'0912000000'.$i],['name'=>"ویزیتور $i",'username'=>"visitor$i",'email'=>"visitor$i@example.test",'password'=>Hash::make('Password123!')]);$u->syncRoles('Visitor');return $u;});$products=collect(range(1,10))->map(fn($i)=>Product::firstOrCreate(['code'=>"PR-$i"],['name'=>"محصول نمونه $i",'unit'=>'kg','price'=>150000+$i*10000,'active'=>true]));$customers=collect(range(1,10))->map(fn($i)=>Customer::firstOrCreate(['customer_code'=>"CUS-$i"],['name'=>"مشتری نمونه $i",'company_name'=>"فروشگاه نمونه $i",'mobile'=>"09121111".str_pad($i,3,'0',STR_PAD_LEFT),'address'=>"تهران، خیابان نمونه، پلاک $i",'city'=>'تهران']));foreach(range(1,20) as $i){$p=$products[$i%10];$weight=10+$i;$o=Order::firstOrCreate(['order_number'=>sprintf('SP-%05d',10000+$i)],['customer_id'=>$customers[$i%10]->id,'visitor_id'=>$visitors[$i%3]->id,'order_date'=>today(),'delivery_date'=>today(),'total_weight'=>$weight,'total_amount'=>$weight*$p->price,'status'=>OrderStatus::Assigned,'notes'=>'سفارش نمونه']);OrderItem::firstOrCreate(['order_id'=>$o->id,'product_id'=>$p->id],['quantity'=>$weight,'weight'=>$weight,'unit_price'=>$p->price,'total_price'=>$weight*$p->price]);app(DeliveryService::class)->issueCode($o->fresh('customer'));}}}
